    "showcase.desc_restaurant": "• Categorized digital dining menu ordering\n• Shopping cart management & order summary\n• Instant bill calculation & live invoice receipts",
    "showcase.desc_ecommerce": "• Consumer electronics showcase & category filter\n• Cart management & order checkout\n• Instant invoicing & digital receipt view",
    "showcase.desc_tn01": "• Comprehensive online course catalog & lessons\n• Progress tracking & interactive quizzes\n• Automated student course certification",
    "showcase.desc_tn03": "• Dermatological skin analysis & routine guide\n• Ingredient filtering tailored for skin types\n• Online cart & checkout order confirmation",
    "showcase.desc_tn04": "• Interactive route mapping & location search\n• Itinerary planning & transit estimation\n• Popular landmark & check-in recommendations",
    "showcase.desc_tn05": "• Online doctor appointment & department search\n• Health checkup packages & medical directory\n• Personal health records & diagnostic reports",
    "showcase.desc_tn06": "• Thai Speech-to-Text, Text-to-Speech & Voice Clone\n• Conversational AI chatbot & language model APIs\n• Developer SDK documentation & subscription plans",
    "showcase.desc_tn07": "• Digital dining menu & online table reservation\n• Customized food ordering & ingredient tweaks\n• Real-time order summary & instant billing",
    "showcase.desc_tn09": "• Real-time Speech-to-Speech voice translation\n• Natural Text-to-Speech (TTS) voice synthesis\n• Multilingual voice conversion & audio playback",
    "showcase.desc_tn10": "• AC technician scheduling & maintenance booking\n• Transparent service pricing & packages\n• Live technician status tracking",
    "showcase.desc_tn11": "• Licensed pharmacist online consultation\n• Initial symptom guidance & medication prescription\n• Safe home drug delivery service",
    "showcase.desc_tn14": "• Specialty coffee bean ordering & bakery menu\n• Custom roast, sweetness & topping selectors\n• Pre-order scheduling & loyalty reward points",
    "showcase.desc_tn12": "• Real estate & housing search platform\n• Virtual property showcases & project catalog\n• Online agent consultations & appointment scheduling",
    "showcase.desc_tn15": "• Medical spa & wellness booking buddy\n• Treatment packages & specialist consultations\n• Online appointment reservation & instant confirmation",
    "showcase.desc_tn16": "• Comprehensive fitness & workout platform\n• Workout scheduling, trainer booking & progress tracking\n• Personalized nutrition guidance & meal planning",
    "showcase.desc_tn17": "• AI platform for e-commerce shops\n• Chat response, sales closing & product recommendations\n• 24/7 automated inventory checks & customer support",
