    "about.badge": "Who We Are",
    "about.title": "Pioneering Localized AI Solutions",
    "about.subtitle": "Founded in 2017 in Bangkok, Botnoi Group has become one of Southeast Asia's leading Enterprise AI companies. We build localized AI solutions designed for multilingual and multicultural markets, helping organizations deploy AI that understands local languages, business practices, and customer expectations.",
    "about.intro_lead": "Founded in 2017 in Bangkok, Botnoi Group has become one of Southeast Asia's leading Enterprise AI companies.",
    "about.intro_sub": "We build localized AI solutions designed for multilingual and multicultural markets, helping organizations deploy AI that understands local languages, business practices, and customer expectations.",
    "about.purpose_title": "Our Purpose",
    "about.vision_title": "Our Vision",
    "about.vision_desc": "To become the leading AI company in Southeast Asia by delivering localized AI that enables every organization to work smarter, communicate better, and innovate with confidence.",
    "about.mission_title": "Our Mission",
    "about.mission_desc": "To solve the shortage of human expertise by making advanced AI practical, secure, and accessible—empowering businesses with AI solutions built for real-world enterprise needs.",
    "about.vision_cta": "Contact Enterprise Team",
    "about.perf_badge": "Proven Impact",
    "about.perf_title": "Our Performance",
    "about.perf_desc": "Over the past eight years, Botnoi has continuously expanded its AI ecosystem, serving enterprises, government organizations, and millions of end users. Today, our technologies power customer service, voice AI, healthcare, education, finance, and enterprise automation across Southeast Asia.",
    "about.stat1_num": "100+",
    "about.stat1_title": "Enterprise Projects",
    "about.stat1_desc": "Successfully delivered AI solutions for enterprises and public organizations.",
    "about.stat2_num": "10+",
    "about.stat2_title": "AI Products",
    "about.stat2_desc": "Comprehensive AI platforms covering Voice AI, Chatbots, Translation, Healthcare, and Automation.",
    "about.stat3_num": "10M+",
    "about.stat3_title": "End Users",
    "about.stat3_desc": "Millions of users interact with Botnoi AI products every month.",
    "about.stat4_num": "20M+",
    "about.stat4_title": "Partner MOUs",
    "about.stat4_desc": "Strategic collaborations with universities, enterprises, and government organizations.",
    "about.journey_badge": "Milestones",
    "about.journey_title": "Our Journey",
    "about.journey_subtitle": "A Decade of AI Innovation",
    "about.journey_desc": "Since 2016, BOTNOI has continuously expanded its AI capabilities—from award-winning chatbot technology to enterprise AI platforms, voice AI, strategic global partnerships, and next-generation AI solutions. Every milestone reflects our commitment to helping businesses adopt AI with confidence and measurable impact.",
    "about.t_2016_title": "LINE Bot Awards Winner",
    "about.t_2016_desc": "• Winner of the prestigious regional LINE Bot Awards\n• Pioneered localized conversational AI and Thai NLP architectures",
    "about.t_2017_title": "First Enterprise Customer",
    "about.t_2017_desc": "• Successfully onboarded first major enterprise customer\n• Deployed automated customer service intelligence at production scale",
    "about.t_2018_title": "Chatbot Platform Launch",
    "about.t_2018_desc": "• Public launch of the low-code Botnoi Chatbot creation platform\n• Reached thousands of SME businesses and developer communities",
    "about.t_2023_title": "BOTNOI Voice Platform Launch",
    "about.t_2023_desc": "• Launched state-of-the-art BOTNOI Voice TTS & voice cloning platform\n• Integrated over 100+ natural synthetic Southeast Asian voices",
    "about.t_2024_title": "AWS Strategic Partner",
    "about.t_2024_desc": "• Formed strategic enterprise AI partnership with Amazon Web Services (AWS)\n• Expanded scalable Generative AI and cloud inference infrastructure",
    "about.t_2025_title": "Voicebot Platform Launch",
    "about.t_2025_desc": "• Official launch of the real-time AI Voicebot telephony platform\n• Automated high-volume inbound customer support and outbound calls",
    "about.t_2026_title": "100+ Enterprise Customers",
    "about.t_2026_desc": "• Milestone achieved: 100+ enterprise corporate and public sector clients\n• Over 10M+ monthly active user interactions across Southeast Asia",
    "about.t_2027_title": "AI Avatar Platform Launch",
    "about.t_2027_desc": "• Launch of next-generation 3D interactive WebAvatar platform\n• Autonomous web navigation agents with real-time conversational intelligence",
    "about.gap_title": "The Expertise Gap",
    "about.gap_desc": "Businesses face a growing shortage of skilled professionals while customer expectations continue to rise. Botnoi AI helps organizations scale expert knowledge, deliver consistent service, reduce costs, and accelerate innovation.",
    "about.pillar1_tag": "SCALE EXPERTISE",
    "about.pillar1_title": "Scale Expert Knowledge",
    "about.pillar1_desc": "Capture and replicate domain expertise with AI, available 24/7.",
    "about.pillar2_tag": "24/7 SERVICE",
    "about.pillar2_title": "Consistent 24/7 Service",
    "about.pillar2_desc": "Deliver accurate, reliable responses anytime with consistent quality.",
    "about.pillar3_tag": "INNOVATION",
