    "site2026.title": "งาน SITE 2026",
    "site2026.badge": "Global Innovation Impact: The Year of Investment",
    "site2026.hero_title": "Startup x Innovation Thailand Expo 2026",
    "site2026.hero_subtitle": "25 - 27 มิถุนายน 2026 ณ ศูนย์การประชุมแห่งชาติสิริกิติ์ (QSNCC)",
    "site2026.about_title": "เกี่ยวกับ SITE 2026",
    "site2026.about_desc": "สำนักงานนวัตกรรมแห่งชาติ (องค์การมหาชน) หรือ NIA ได้เล็งเห็นความสำคัญในการพัฒนาระบบนวัตกรรมแห่งชาติและระบบนิเวศสตาร์ตอัปมาอย่างต่อเนื่อง ในปีนี้ จึงได้กำหนดจัดงาน Startup x Innovation Thailand Expo 2026 หรือ SITE 2026 ภายใต้แนวคิดหลัก Global Innovation Impact: The Year of Investment เพื่อรวบรวมเครือข่ายนวัตกรรมจากพันธมิตรทั่วโลก ยกระดับความร่วมมือและส่งเสริมการสร้างองค์ความรู้เพื่อพัฒนาระบบนิเวศนวัตกรรมและระบบนิเวศสตาร์ตอัปให้แข็งแกร่ง ก่อให้เกิดการลงทุน และมุ่งเน้นการสร้างผลกระทบเชิงระบบ ทั้งทางด้านเศรษฐกิจ สังคม และสิ่งแวดล้อม ตั้งแต่ระดับท้องถิ่นสู่ระดับสากล",
    "site2026.objective_title": "วัตถุประสงค์",
    "site2026.objective_1": "1. ยกระดับความร่วมมือทางนวัตกรรมของหน่วยงานจากทุกภาคส่วนในระบบนิเวศนวัตกรรม ทั้งในประเทศและต่างประเทศ",
    "site2026.objective_2": "2. สร้างโอกาสและส่งเสริมสตาร์ตอัปและผู้ประกอบการฐานนวัตกรรม",
    "site2026.objective_3": "3. สร้างเครือข่ายความร่วมมือทางธุรกิจและนวัตกรรมระหว่างประเทศ เพื่อรองรับการขยายตัวทางเศรษฐกิจในระดับสากล",
    "site2026.activities_title": "กิจกรรมหลัก",
    "site2026.activity_forum_title": "การสัมมนา (Forum)",
    "site2026.activity_forum_desc": "กิจกรรมเผยแพร่เนื้อหาองค์ความรู้และสร้างความเข้าใจเกี่ยวกับการดำเนินธุรกิจนวัตกรรมที่ประสบความสำเร็จ โดยเฉพาะเรื่องปัญญาประดิษฐ์และความยั่งยืน",
    "site2026.activity_exhibition_title": "นิทรรศการ (Exhibition)",
    "site2026.activity_exhibition_desc": "นิทรรศการของผู้ประกอบการฐานนวัตกรรมและสตาร์ตอัป เพื่อสร้างโอกาสทางธุรกิจ เพิ่มรายได้ และกระตุ้นการลงทุน",
    "site2026.activity_match_title": "การจับคู่ธุรกิจ (Business Matching)",
    "site2026.activity_match_desc": "กิจกรรมจับคู่ธุรกิจให้เกิดการลงทุนและต่อยอดทางธุรกิจในสตาร์ตอัปหรือผู้ประกอบการฐานนวัตกรรม กับนักลงทุนหรือองค์กรขนาดใหญ่",
    "site2026.activity_pitch_title": "การนำเสนอแผนธุรกิจ (Pitching)",
    "site2026.activity_pitch_desc": "การแข่งขันนำเสนอแผนธุรกิจ สตาร์ตอัปและผู้ประกอบการฐานนวัตกรรม ในระยะเริ่มต้นและระยะเติบโต",
    "site2026.activity_pma_title": "รางวัลนายกรัฐมนตรี (Prime Minister’s Award)",
    "site2026.activity_pma_desc": "พิธีมอบรางวัลประกาศเกียรติคุณและเชิดชูเกียรติจากนายกรัฐมนตรีให้แก่สตาร์ตอัป บริษัทและบุคคลในสาขาธุรกิจเป้าหมายที่มีศักยภาพสูง",
    "site2026.agenda_title": "กำหนดการจัดงาน (Agenda)",
    "site2026.search_placeholder": "ค้นหาผู้พูด หัวข้อ หรือกิจกรรม...",
