    "home.card_alldemo_desc": "• ศูนย์รวมระบบจำลองแซนด์บอกซ์ทั้งหมด (จองเที่ยวบิน, ร้านค้าไอที, สั่งอาหาร, จองโรงแรม)\n• รวบรวมผลงานโครงการเว็บแอปพลิเคชันจากทีมพัฒนา StartUP (TN01–TN20)\n• ระบบค้นหา กรองหมวดหมู่ และเปิดดูตัวอย่างเว็บไซต์จำลองจริง",
    "home.card_alldemo_cta": "เปิดพอร์ทัลรวมเดโม",
    "home.card_itstore_title": "ร้านค้าไอที อีคอมเมิร์ซ",
    "home.card_itstore_desc": "• แหล่งรวมแก็ดเจ็ตและคัดกรองหมวดหมู่สินค้าไอที\n• ระบบจัดการตะกร้าสินค้าและสั่งซื้อสินค้า\n• ระบบชำระเงินและออกใบเสร็จรับเงินออนไลน์",
    "home.card_itstore_cta": "เปิดร้านไอทีจำลอง",
    "home.card_hotel_title": "โรงแรม Botnoi",
    "home.card_hotel_desc": "• ค้นหาห้องพักและเช็คสถานะห้องว่างเรียลไทม์\n• เลือกวันเข้าพักและคำนวณราคาอัตโนมัติ\n• ระบบยืนยันการจองและออกใบรับรองครบวงจร",
    "home.card_hotel_cta": "เปิดระบบจองโรงแรมจำลอง",
    "home.card_contact_title": "แบบฟอร์มติดต่อธุรกิจ B2B",
    "home.card_contact_desc": "• แบบฟอร์มเก็บข้อมูลผู้สนใจระบบรองรับการตรวจสอบข้อมูลอินพุต\n• เลือกประเภทการสอบถามข้อมูลด้วย Dropdown ไดนามิก และ FAQ แบบ Accordion\n• ระบบตารางรายชื่อและบันทึกผู้ติดต่อสำหรับผู้ดูแลระบบ",
    "home.card_contact_cta": "เปิดแบบฟอร์มผู้สนใจจำลอง",
