    "food_item.tomyum.name": "ต้มยำกุ้งน้ำข้น",
    "food_item.tomyum.desc": "กุ้งแม่น้ำสดตัวโตในน้ำซุปต้มยำน้ำข้นเข้มข้น หอมสมุนไพร ข่า ตะไคร้ ใบมะกรูดครบครัน",
    "food_item.greencurry.name": "แกงเขียวหวานไก่",
    "food_item.greencurry.desc": "พริกแกงเขียวหวานตำสด เคี่ยวกับน้ำกะทิหอมมัน มะเขือเปราะ และเนื้อไก่เสิร์ฟพร้อมข้าวสวยร้อน ๆ",
    "food_item.mangorice.name": "ข้าวเหนียวมะม่วง",
    "food_item.mangorice.desc": "มะม่วงอกร่องสุกรสหวานหอมทานคู่กับข้าวเหนียวมูนราดกะทิสดโรยถั่วทองทอดกรอบ",
    "food_item.friedrice.name": "ข้าวผัดกุ้ง",
    "food_item.friedrice.desc": "ข้าวหอมมะลิผัดไฟแรงหอมกลิ่นกระทะ ใส่ไข่ กุ้งสดตัวโต แครอทและต้นหอมซอยตกแต่ง",
    "food_item.tomyumnoodle.name": "ก๋วยเตี๋ยวต้มยำ",
    "food_item.tomyumnoodle.desc": "ก๋วยเตี๋ยวต้มยำหมูสับเส้นนุ่ม น้ำซุปรสจัดจ้านพริกเผามะนาวแท้ โรยด้วยถั่วคั่วป่นหอมใหม่",
