    "showcase.launch_demo": "เปิดดูระบบเดโม",
    "showcase.no_projects": "ไม่พบผลงานโครงการ",
    "showcase.no_projects_desc": "กรุณาลองปรับปรุงคำค้นหาหรือตัวกรองใหม่อีกครั้ง",
    "showcase.desc_accommodation": "• ค้นหาห้องพักและเช็คสถานะห้องว่างเรียลไทม์\n• เลือกวันเข้าพักและคำนวณราคาอัตโนมัติ\n• ระบบยืนยันการจองและออกใบรับรองครบวงจร",
    "showcase.desc_flight": "• ค้นหาเที่ยวบินและระบุจำนวนผู้โดยสาร\n• เลือกที่นั่งและจำลองการออกบอร์ดดิ้งพาส\n• ระบบจองตั๋วเครื่องบินในประเทศแบบครบวงจร",
    "showcase.desc_restaurant": "• เมนูอาหารดิจิทัลคัดแยกหมวดหมู่\n• ระบบจัดการตะกร้าสินค้าและสรุปรายการ\n• คำนวณยอดชำระและพิมพ์ใบเสร็จเรียลไทม์",
    "showcase.desc_ecommerce": "• แหล่งรวมแก็ดเจ็ตและคัดกรองหมวดหมู่สินค้าไอที\n• ระบบจัดการตะกร้าสินค้าและสั่งซื้อสินค้า\n• ระบบชำระเงินและออกใบเสร็จรับเงินออนไลน์",
    "showcase.desc_tn01": "• ค้นหาบทเรียนและคอร์สเรียนออนไลน์\n• ระบบติดตามความก้าวหน้าและแบบทดสอบ\n• ออกวุฒิบัตรจำลองหลังเรียนจบ",
    "showcase.desc_tn03": "• แหล่งรวมเวชสำอางและรูทีนดูแลผิวพรรณ\n• คัดกรองส่วนผสมตามสภาพผิว\n• ระบบตะกร้าสินค้าและชำระเงินออนไลน์",
    "showcase.desc_tn04": "• ค้นหาสถานที่และวางแผนการเดินทางอินเทอร์แอคทีฟ\n• คำนวณเส้นทางและเวลาเดินทาง\n• แนะนำจุดเช็คอินและสถานที่ท่องเที่ยวสำคัญ",
    "showcase.desc_tn05": "• นัดหมายแพทย์และค้นหาแผนกรักษาออนไลน์\n• เลือกแพ็กเกจตรวจสุขภาพและศูนย์การแพทย์\n• ระบบบริการข้อมูลและรายงานผลสุขภาพ",
    "showcase.desc_tn06": "• บริการ AI เสียงภาษาไทย (STT, TTS, Voice Clone)\n• แชตบอตสนทนา AI และระบบวิเคราะห์ภาษา\n• เอกสาร API SDK และแพ็กเกจสมัครใช้งาน",
    "showcase.desc_tn07": "• เมนูอาหารดิจิทัลและระบบจองโต๊ะออนไลน์\n• สั่งอาหารพร้อมปรับแต่งรสชาติและส่วนผสม\n• สรุปรายการสั่งซื้อและใบเสร็จเรียลไทม์",
    "showcase.desc_tn09": "• ระบบแปลภาษาแบบ Speech-to-Speech เรียลไทม์\n• สังเคราะห์เสียงพูด (TTS) ถ่ายทอดน้ำเสียงธรรมชาติ\n• รองรับการแปลและเล่นเสียงหลายภาษา",
    "showcase.desc_tn10": "• ระบบนัดหมายช่างล้างแอร์และซ่อมบำรุงออนไลน์\n• ตรวจสอบราคาแพ็กเกจบริการโปร่งใส\n• ติดตามสถานะงานช่างเรียลไทม์",
    "showcase.desc_tn11": "• ปรึกษาเรื่องยากับเภสัชกรผู้เชี่ยวชาญออนไลน์\n• ประเมินอาการเบื้องต้นและรับคำแนะนำด้านยา\n• สั่งซื้อยาตามใบสั่งและบริการจัดส่งถึงบ้าน",
    "showcase.desc_tn14": "• เมนูกาแฟสด สเปเชียลตี้ และเบเกอรี่\n• ปรับเลือกเมล็ดกาแฟ ระดับความหวาน และท็อปปิ้ง\n• สั่งซื้อล่วงหน้าและระบบสะสมแต้มสมาชิก",
    "showcase.desc_tn12": "• แพลตฟอร์มค้นหาบ้านและอสังหาริมทรัพย์\n• โชว์รูมบ้านเสมือนจริงและแคตตาล็อกโครงการ\n• นัดหมายเข้าชมและปรึกษาตัวแทนออนไลน์",
    "showcase.desc_tn15": "• บริการจองคิวสปา นวดผ่อนคลาย และทรีตเมนต์เพื่อสุขภาพ\n• เลือกแพ็กเกจการนวดและปรึกษาผู้เชี่ยวชาญ\n• ระบบจองคิวออนไลน์และชำระเงินสะดวกรวดเร็ว",
    "showcase.desc_tn16": "• แพลตฟอร์มฟิตเนสและออกกำลังกายครบวงจร\n• จัดตารางฝึก นัดหมายเทรนเนอร์ส่วนตัว และติดตามผลลัพธ์\n• คำแนะนำโภชนาการและวางแผนการทานอาหารเฉพาะบุคคล",
    "showcase.desc_tn17": "• แพลตฟอร์ม AI สำหรับร้านค้าออนไลน์\n• ตอบแชต ปิดการขาย แนะนำสินค้า และเช็คสต็อก\n• บริการดูแลและตอบคำถามลูกค้าอัตโนมัติ 24 ชม.",
