    "showcase.desc_tn08": "• โชว์รูมเสมือนจริงและแคตตาล็อกเฟอร์นิเจอร์\n• ไอเดียการดีไซน์ตกแต่งห้องสไตล์ต่าง ๆ\n• ระบบสั่งซื้อและชำระเงินออนไลน์ครบวงจร",
