    "about.badge": "เกี่ยวกับเรา",
    "about.title": "ผู้นำนวัตกรรมโซลูชัน AI ภาษาและบริบทท้องถิ่น",
    "about.subtitle": "ก่อตั้งขึ้นในปี 2017 ณ กรุงเทพฯ บอทน้อย กรุ๊ป (Botnoi Group) ได้ก้าวขึ้นเป็นหนึ่งในบริษัท Enterprise AI ชั้นนำของเอเชียตะวันออกเฉียงใต้ เราพัฒนานวัตกรรม AI ที่เข้าใจบริบททางภาษาและวัฒนธรรมท้องถิ่น เพื่อช่วยให้องค์กรปรับใช้ AI ที่เข้าใจภาษา ธรรมเนียมธุรกิจ และความคาดหวังของลูกค้าได้อย่างแท้จริง",
    "about.intro_lead": "ก่อตั้งขึ้นในปี 2017 ณ กรุงเทพฯ บอทน้อย กรุ๊ป (Botnoi Group) ได้ก้าวขึ้นเป็นหนึ่งในบริษัท Enterprise AI ชั้นนำของเอเชียตะวันออกเฉียงใต้",
    "about.intro_sub": "เราพัฒนานวัตกรรม AI ที่เข้าใจบริบททางภาษาและวัฒนธรรมท้องถิ่น เพื่อช่วยให้องค์กรปรับใช้ AI ที่เข้าใจภาษา ธรรมเนียมธุรกิจ และความคาดหวังของลูกค้าได้อย่างแท้จริง",
