    "itstore_item.acc2.desc": "แท่นชาร์จไร้สาย 3-in-1 ผลิตจากอะลูมิเนียมเกรดพรีเมียม พับเก็บพกพาง่าย ชาร์จสมาร์ทโฟน นาฬิกา และหูฟังได้พร้อมกัน",
    "itstore_item.acc3.name": "Botnoi USB-C Hub 8-in-1",
    "itstore_item.acc3.specs": "ต่อจอ HDMI 4K@60Hz · ชาร์จเร็ว PD 100W · พอร์ต USB 3.2 10Gbps · ช่องอ่าน SD/TF",
    "itstore_item.acc3.desc": "ฮับแปลงพอร์ต USB-C อเนกประสงค์ 8-in-1 บอดี้อะลูมิเนียมระบายความร้อนดีเยี่ยม รองรับต่อจอภาพ 4K คมชัดและถ่ายโอนไฟล์เร็วสูง",
    "itstore_item.acc4.name": "Botnoi Mechanical Keypad",
    "itstore_item.acc4.specs": "แป้นตัวเลขกลไก 21 ปุ่ม Hot-swap · ปุ่มหมุนปรับเสียงตั้งโปรแกรมได้ · บอดี้อะลูมิเนียม",
    "itstore_item.acc4.desc": "คีย์แพดตัวเลขแมคคานิคอลคัสตอม พร้อมปุ่มหมุน Rotary Knob ปรับระดับเสียงและตั้งค่า Macro ช่วยเพิ่มความเร็วในการทำงาน",
    "itstore_item.acc5.name": "Botnoi Vertical Ergonomic Mouse",
    "itstore_item.acc5.specs": "มุมจับ 57° ตามสรีรศาสตร์ธรรมชาติ · เซ็นเซอร์ความละเอียด 4000 DPI · คลิกเงียบ",
    "itstore_item.acc5.desc": "เมาส์แนวตั้งเพื่อสุขภาพมุมจับ 57 องศา ลดการบิดของกล้ามเนื้อแขนและข้อมือ เซ็นเซอร์แม่นยำ 4000 DPI และปุ่มคลิกเงียบ",
    "itstore_item.acc6.name": "Botnoi MagDesk Studio Arm",
    "itstore_item.acc6.specs": "แขนจับจอมอนิเตอร์คู่ระบบแก๊สสปริง · ซ่อนสายไฟเนียนตา · เพลท VESA ถอดใส่ง่าย",
    "itstore_item.acc6.desc": "แขนจับจอคู่เกรดพรีเมียม รับน้ำหนักจอใหญ่ได้ถึง 40 นิ้ว ปรับมุมมองหมุนเอียงได้อย่างอิสระและนุ่มนวล",
    "itstore_item.acc7.name": "Botnoi SmartStream Deck 15",
    "itstore_item.acc7.specs": "ปุ่มคีย์ลัดหน้าจอ LCD 15 ปุ่มปรับแต่งได้ · สลับซีนสตรีมมิ่งทันที · รองรับปลั๊กอิน",
    "itstore_item.acc7.desc": "คอนโทรลเลอร์สำหรับครีเอเตอร์และสตรีมเมอร์ ปุ่ม LCD 15 ปุ่มตั้งภาพและคำสั่งมาโครได้ตามใจ สลับฉากและเปิดแอปได้ในคลิกเดียว",
    "itstore_item.acc8.name": "Botnoi GaN UltraPower 140W",
    "itstore_item.acc8.specs": "หัวชาร์จเร็ว 140W 4 พอร์ต USB-C/A · เทคโนโลยี GaN III · รองรับ PD 3.1 และ QC 5.0",
    "itstore_item.acc8.desc": "อะแดปเตอร์ชาร์จเร็ว GaN III ขนาดกะทัดรัด จ่ายไฟสูงสุด 140W ชาร์จโน้ตบุ๊กประสิทธิภาพสูงและสมาร์ทโฟนพร้อมกันได้อย่างรวดเร็ว",
    "itstore_item.phone7.name": "HUAWEI Pura 70 Ultra",
    "itstore_item.phone7.specs": "จอ 6.8\" 120Hz LTPO OLED · กล้อง Ultra Lighting Pop-up 1 นิ้ว · RAM 16GB + 512GB · ชาร์จเร็ว 100W",
    "itstore_item.phone7.desc": "สมาร์ทโฟนเรือธงด้านการถ่ายภาพด้วยกล้อง Ultra Lighting แบบยืดหดได้ขนาด 1 นิ้ว กระจก Crystal Armor Kunlun Glass และระบบชาร์จเร็ว 100W SuperCharge",
    "itstore_item.phone8.name": "HUAWEI Pocket 2",
    "itstore_item.phone8.specs": "จอพับ 6.94\" 120Hz OLED + จอนอก 1.15\" · RAM 12GB + ROM 256GB · กล้อง XMAGE Quad",
    "itstore_item.phone8.desc": "สมาร์ทโฟนจอพับทรงตลับแป้ง พกพาสะดวก หน้าจอด้านนอกใช้งานสะดวก ถ่ายเซลฟี่และวิดีโอได้โดยไม่ต้องกางเครื่อง พร้อมกล้อง XMAGE 4 ตัว",
    "itstore_item.phone9.name": "HUAWEI Mate 60 RS Ultimate Design",
    "itstore_item.phone9.specs": "จอ 6.82\" 120Hz LTPO OLED · บอดี้เซรามิก · RAM 16GB + 512GB · โทรผ่านดาวเทียม",
    "itstore_item.phone9.desc": "สมาร์ทโฟนระดับอัลตร้าลักชัวรีดีไซน์เซรามิก Star Diamond เอกลักษณ์เฉพาะตัว รองรับการโทรผ่านดาวเทียมคู่ กระจก Kunlun Glass แข็งแกร่งสูงสุด",
