    "site2026.title": "SITE 2026 活动页面",
    "site2026.badge": "全球创新影响：投资年",
    "site2026.hero_title": "2026 年泰国创业 x 创新博览会",
    "site2026.hero_subtitle": "2026 年 6 月 25 日至 27 日在诗丽吉王后国家会议中心 (QSNCC)",
    "site2026.about_title": "关于网站 2026",
    "site2026.about_desc": "国家创新机构（公共组织）或 NIA 认识到持续发展国家创新体系和创业生态系统的重要性。今年，Startup x Innovation Thai Expo 2026（简称 SITE 2026）以“全球创新影响力：投资年”为理念举办，旨在聚集全球创新网络，提升合作，促进知识共享，以加强生态系统。",
    "site2026.objective_title": "目标",
    "site2026.objective_1": "1. 加强本地和国际生态系统中所有部门（政府、私营部门、学术界、协会）之间的创新合作。",
    "site2026.objective_2": "2.创造商机，支持创业创新企业。",
    "site2026.objective_3": "3. 在东南亚和全球建立国际商业和创新网络，以支持经济扩张。",
    "site2026.activities_title": "主要活动",
    "site2026.activity_forum_title": "论坛",
    "site2026.activity_forum_desc": "研讨会分享成功创新企业的知识和商业实践，重点关注协作、人工智能和可持续发展。",
    "site2026.activity_exhibition_title": "展览",
    "site2026.activity_exhibition_desc": "展示创新型企业和初创企业，创造商机、增加收入、刺激投资。",
    "site2026.activity_match_title": "商贸配对",
    "site2026.activity_match_desc": "为初创企业和创新型企业与大型企业提供投资和业务扩展的商业配对活动。",
    "site2026.activity_pitch_title": "投球",
    "site2026.activity_pitch_desc": "为早期和成长阶段的初创企业和创新型企业提供竞争的商业计划。",
    "site2026.activity_pma_title": "内阁总理大臣奖",
    "site2026.activity_pma_desc": "总理举行颁奖仪式，表彰支持生态系统的高潜力初创企业、企业和个人。",
    "site2026.agenda_title": "活动议程",
