    "contact.faq_heading": "常见问题解答",
    "contact.faq_subheading": "阅读有关我们服务的快速解答。您的网络头像可以滚动到此处查看详细信息！",
    "contact.faq_q1": "什么是 WebAvatar？它如何集成到我的网站中？",
    "contact.faq_a1": "WebAvatar 是一个通过轻量级 JavaScript SDK（我们的自定义脚本标签）加载的视觉数字人类助手。它在标准浏览器 Web 层内运行，可以导航页面、滚动到指定的 HTML 元素（如 #pricing）、触发本机单页应用程序 (SPA) 路由，并使用合成语音口头引导访问者。",
    "contact.faq_q2": "语音模型是否支持连续的泰语声学？",
    "contact.faq_a2": "是的。我们的生成语音模型经过区域音频档案的训练，为连续的泰国方言提供丰富的声学映射，并具有适合当地受众的自然节奏、单词桥接和音调变化。",
    "contact.faq_q3": "我可以自定义数字化身的视觉外观吗？",
    "contact.faq_a3": "绝对地。 Botnoi Group 支持定制 3D 模型装备、视觉主题皮肤和专业品牌表现。我们可以直接以您公司的吉祥物、公众人物或虚拟品牌大使为模型构建头像。",
    "contact.faq_q4": "Botnoi集团的执行创始人是谁？",
    "contact.faq_a4": "Winn 博士是 Botnoi 集团富有远见的创始人兼首席执行官。他在曼谷瓦他那总部协调我们的核心人工智能研究部门、语音技术实验室和数字化身集成。",
