    "showcase.no_projects_desc": "请尝试调整您的搜索过滤器或查询。",
    "showcase.desc_accommodation": "• 实时客房目录与空房查询\n• 交互式日期选择与自动计价\n• 完整预订确认与凭证展示",
    "showcase.desc_flight": "• 国内航班搜索与乘客配置\n• 交互式座位图与模拟登机牌生成\n• 端到端航空公司预订系统",
    "showcase.desc_restaurant": "• 分类数字餐饮菜单点餐\n• 购物车管理与订单汇总\n• 实时账单计算与电子发票",
    "showcase.desc_ecommerce": "• 消费电子产品展示与分类筛选\n• 购物车管理与订单结账\n• 实时发票与数字收据查看",
    "showcase.desc_tn01": "• 综合在线课程目录与视频教学\n• 学习进度跟踪与互动测验\n• 结业自动生成模拟证书",
    "showcase.desc_tn03": "• 皮肤状况分析与护肤方案推荐\n• 适合不同肤质的成分筛选\n• 在线购物车与结账确认",
    "showcase.desc_tn04": "• 路线规划与地点搜索\n• 行程安排与交通用时估算\n• 地标与热门景点推荐",
    "showcase.desc_tn05": "• 在线医生预约与科室查询\n• 体检套餐与医疗中心目录\n• 个人健康档案与诊断报告",
    "showcase.desc_tn06": "• 泰语语音转文字、语音合成与声音克隆\n• 对话式 AI 聊天机器人与语言模型 API\n• 开发者 SDK 文档与订阅套餐",
    "showcase.desc_tn07": "• 数字餐饮菜单与在线订座系统\n• 自定义点餐与口味食材微调\n• 实时订单汇总与电子账单",
    "showcase.desc_tn08": "• 虚拟展厅与家具展示目录\n• 室内设计灵感与家居搭配\n• 无缝在线订购与结账",
    "showcase.desc_tn09": "• 实时语音到语音双向翻译\n• 自然语音合成 (TTS) 与音色转换\n• 多语言语音播放与即时翻译",
    "showcase.desc_tn10": "• 空调清洗与维修技术人员预约\n• 透明的服务价格与清洗套餐\n• 实时跟踪技术人员服务状态",
    "showcase.desc_tn11": "• 执业药师在线用药咨询指导\n• 初始症状评估与处方建议\n• 安全送药到家服务",
    "showcase.desc_tn12": "• 房产与住宅搜索平台\n• 虚拟看房与项目展厅目录\n• 在线经纪人咨询与预约看房",
    "showcase.desc_tn14": "• 精品咖啡豆订购与烘焙菜单\n• 自定义烘焙度、甜度与配料\n• 提前预约自提与会员积分",
    "showcase.desc_tn15": "• 医疗水疗与健康体验预约\n• 疗程套餐与专家咨询\n• 在线预约与即时确认",
    "showcase.desc_tn16": "• 综合健身与训练计划平台\n• 课程预约、私教指导与进度跟踪\n• 个性化营养建议与饮食规划",
    "showcase.desc_tn17": "• 电商在线智能 AI 平台\n• 智能客服、销售闭环与商品推荐\n• 24/7 实时库存查询与自动服务",
    "showcase.desc_tn19": "• 虚拟展厅与家具展示目录\n• 室内设计灵感与家居搭配\n• 无缝在线订购与结账",
