    "about.badge": "关于我们",
    "about.title": "开拓本地化人工智能解决方案",
    "about.subtitle": "Botnoi Group 于 2017 年在曼谷成立，现已成长为东南亚领先的企业级 AI 公司之一。我们构建适应多语言与多元文化市场的本地化 AI 解决方案，帮助组织部署真正理解当地语言、商业习惯与客户期望的 AI。",
    "about.intro_lead": "Botnoi Group 于 2017 年在曼谷成立，现已成长为东南亚领先的企业级 AI 公司之一。",
    "about.intro_sub": "我们构建适应多语言与多元文化市场的本地化 AI 解决方案，帮助组织部署真正理解当地语言、商业习惯与客户期望的 AI。",
    "about.purpose_title": "我们的宗旨",
    "about.vision_title": "我们的愿景",
    "about.vision_desc": "成为东南亚领先的 AI 公司，通过提供理解本地背景的 AI 解决方案，帮助每个组织更智慧地工作、更顺畅地沟通并满怀信心地创新。",
    "about.mission_title": "我们的使命",
    "about.mission_desc": "通过使先进的 AI 技术切合实际、安全且易于获取，解决专业人才短缺问题——为企业提供专为真实企业需求打造的 AI 解决方案。",
    "about.vision_cta": "联系企业解决方案团队",
    "about.perf_badge": "成效显著",
    "about.perf_title": "我们的成绩与表现",
    "about.perf_desc": "在过去的八年里，Botnoi 持续扩展其 AI 生态系统，服务企业、政府机构以及数百万终端用户。如今，我们的技术已全面赋能东南亚各地的客户服务、语音 AI、医疗健康、教育、金融和企业自动化。",
    "about.stat1_num": "100+",
    "about.stat1_title": "企业级项目",
