    "about.journey_title": "发展历程",
    "about.journey_subtitle": "十年 AI 创新之路",
    "about.journey_desc": "自 2016 年以来，BOTNOI 持续拓展其 AI 实力——从屡获殊荣的聊天机器人技术，到企业级 AI 平台、语音 AI、全球战略合作伙伴关系以及次世代 AI 解决方案。每一个里程碑都印证了我们助力企业自信引入 AI 并取得显著成效的坚定承诺。",
    "about.t_2016_title": "荣获 LINE Bot Awards 大奖",
    "about.t_2016_desc": "• 荣获极具声望的区域级 LINE Bot Awards 冠军\n• 开创本地化对话式 AI 与泰语自然语言处理 (NLP) 架构",
    "about.t_2017_title": "首个大型企业级客户",
    "about.t_2017_desc": "• 成功签约首家大型企业客户\n• 在生产环境中大规模部署自动化智能客服系统",
    "about.t_2018_title": "推出 Chatbot 智能对话平台",
    "about.t_2018_desc": "• 正式向公众推出低代码 Botnoi Chatbot 构建平台\n• 赋能数千家中小微企业与活跃开发者社区",
    "about.t_2023_title": "BOTNOI Voice 平台发布",
    "about.t_2023_desc": "• 推出前沿的 BOTNOI Voice TTS 语音合成与声音克隆平台\n• 集成超过 100+ 款自然逼真的东南亚多语种合成声音",
    "about.t_2024_title": "AWS 战略合作伙伴",
    "about.t_2024_desc": "• 与亚马逊云科技 (AWS) 达成企业级 AI 深度战略合作\n• 全面拓展高可扩展性生成式 AI 与云端推理基础设施",
    "about.t_2025_title": "Voicebot 语音机器人平台上线",
    "about.t_2025_desc": "• 正式上线实时 AI 语音通话机器人平台 (Voicebot)\n• 高效实现海量呼入客服问答与呼出通知电话全自动处理",
    "about.t_2026_title": "突破 100+ 家大型企业客户",
    "about.t_2026_desc": "• 达成突破：服务超过 100+ 家领军企业和公共事业机构\n• 东南亚地区每月活跃用户互动量突破 1000 万次",
    "about.t_2027_title": "AI 虚拟人化身平台发布",
    "about.t_2027_desc": "• 全新推出次世代 3D 交互式 WebAvatar 虚拟人平台\n• 具备实时对话智能与网页自主导览交互的 AI 数字人代理",
    "about.gap_title": "弥合专业知识断层",
