    "home.badge": "ウェブアバターサンドボックス",
    "home.hero_title": "デジタル担当者に\n会う",
    "home.hero_subtitle": "Botnoi Group は、究極の WebAvatar エージェントのショーケースを紹介します。この統合サンドボックスには、自動音声、フォーム入力、ページ ルーティング用に構成された 3 つのローカライズされたビジネス アプリケーションが備えられています。",
