    "home.mockup_title": "WebAvatarデジタル担当者",
    "home.mockup_desc": "私たちのビジュアル アバターは、Web ページの構造を読み取り、複雑な入力を入力し、ドロップダウン項目を選択し、内部でナビゲーションを処理します。 「フライトの予約に行く」または「グリーン カレーの食事オプションを見せて」などのコマンドを発話してみてください。",
