    "home.card_flight_title": "航空券予約",
    "home.card_flight_desc": "• 国内線フライト検索と乗客数設定\n• インタラクティブな座席マップと搭乗券生成\n• エンドツーエンドの航空券予約シミュレーション",
    "home.card_flight_cta": "フライト予約デモを開始",
    "home.card_food_title": "Botnoi レストラン",
    "home.card_food_desc": "• 写真付きのタイ料理＆国際料理メニューカタログ\n• インタラクティブなショッピングカートと辛さのカスタマイズ\n• リアルタイムの注文送信と音声注文アシスタント",
    "home.card_food_cta": "レストランデモを開始",
    "home.card_alldemo_title": "すべてのデモポータル",
    "home.card_alldemo_desc": "• 対話型サンドボックス全機能（フライト、ITストア、レストラン、ホテル）\n• 学生 StartUP Web プロジェクト展示ポータル (TN01〜TN20)\n• 高度な検索、カテゴリフィルタ、ライブデモ実行",
