    "home.card_itstore_title": "ITストア Eコマース",
    "home.card_itstore_desc": "• 家電製品の展示とカテゴリフィルタリング\n• カート管理と注文決済手続き\n• リアルタイム請求書とデジタル領収書表示",
    "home.card_itstore_cta": "IT ストアのデモを開始",
    "home.card_hotel_title": "Botnoi ホテル",
    "home.card_hotel_desc": "• リアルタイム客室カタログと空室検索\n• インタラクティブな日付選択と自動料金計算\n• 完全な予約確認と証明書表示",
    "home.card_hotel_cta": "ホテル予約デモを開始",
