    "home.tech_title": "ウェブアバターエンジン",
    "home.tech_subtitle": "統合されたエージェントの実行とサイトの相互運用性",
    "home.tech_desc": "標準のテキストベースのボットとは異なり、WebAvatar は DOM をスキャンし、要素と直接対話します。次のルールに従うことで、スムーズなナビゲーションと低いトークン オーバーヘッドを実現します。",
    "home.rule1_title": "イベント駆動型ルーティング",
    "home.rule1_desc": "• ページ遷移のためにキャンセル可能な「webavatar-navigate」CustomEvent を送出\n• シングルページ ルーティングをインターセプトして React Router を更新\n• フル ページのリロードを防ぎ、ライブ音声セッションを維持",
    "home.rule2_title": "宣言型フォーカスフック",
    "home.rule2_desc": "• 一意の DOM 要素 ID (nav-about、nav-contact など) を使用して要素を固定\n• スムーズなスクロールとフォーカル リング アニメーションをトリガー\n• 視覚的なハイライトをアバターの音声と同期",
    "home.rule3_title": "動的フォーム＆入力検証",
    "home.rule3_desc": "• クライアント側フォームを標準の HTML5 入力検証に接続\n• ネイティブ入力イベントを送出して React コンポーネントの状態を更新\n• リアルタイムのフィードバックと成功インジケーターを表示",
    "home.click_to_call": "ロゴをクリックして音声通話を開始",
