    "about.badge": "私たちについて",
    "about.title": "ローカライズされた AI ソリューションのパイオニア",
    "about.subtitle": "Botnoi Group は 2017 年にバンコクで設立され、東南アジアを代表するエンタープライズ AI 企業の一つに成長しました。私たちは、多言語・多文化市場に対応したローカライズ AI ソリューションを構築し、組織が現地の言語、商慣習、顧客期待を理解した AI を導入できるよう支援しています。",
    "about.intro_lead": "Botnoi Group は 2017 年にバンコクで設立され、東南アジアを代表するエンタープライズ AI 企業の一つに成長しました。",
    "about.intro_sub": "私たちは、多言語・多文化市場に対応したローカライズ AI ソリューションを構築し、組織が現地の言語、商慣習、顧客期待を理解した AI を導入できるよう支援しています。",
    "about.purpose_title": "私たちの目的",
    "about.vision_title": "私たちのビジョン",
    "about.vision_desc": "東南アジアで最先端の AI 企業となり、ローカライズされた AI を通じて、すべての組織がよりスマートに働き、より良いコミュニケーションを取り、自信を持ってイノベーションを起こせるよう支援します。",
    "about.mission_title": "私たちのミッション",
    "about.mission_desc": "高度な AI を実用的で安全かつアクセスしやすいものにすることで専門知識の不足を解決し、実際のエンタープライズニーズに対応した AI ソリューションでビジネスを強化します。",
    "about.vision_cta": "エンタープライズチームに連絡",
    "about.perf_badge": "実証済みの実績",
    "about.perf_title": "私たちの実績と成果",
    "about.perf_desc": "過去 8 年間、Botnoi は AI エコシステムを継続的に拡大し、企業、政府機関、数百万のエンドユーザーにサービスを提供してきました。現在、当社の技術は東南アジア全域の顧客サービス、音声 AI、医療、教育、金融、企業自動化を支えています。",
