    "about.journey_badge": "マイルストーン",
    "about.journey_title": "私たちの歩み",
    "about.journey_subtitle": "AI イノベーションの 10 年",
    "about.journey_desc": "2016 年以来、BOTNOI は受賞歴のあるチャットボット技術からエンタープライズ AI プラットフォーム、音声 AI、戦略的グローバルパートナーシップ、次世代 AI ソリューションまで、AI 機能を継続的に拡大してきました。すべてのマイルストーンは、企業が自信を持って AI を導入し、測定可能な成果を達成できるよう支援する私たちの取り組みを反映しています。",
    "about.t_2016_title": "LINE Bot Awards 受賞",
