    "site2026.title": "SITE 2026 이벤트 페이지",
    "site2026.badge": "글로벌 혁신 영향: 투자의 해",
    "site2026.hero_title": "스타트업 x 혁신 태국 엑스포 2026",
    "site2026.hero_subtitle": "2026년 6월 25일~27일, 퀸 시리킷 국립 컨벤션 센터(QSNCC)",
    "site2026.about_title": "사이트 2026 소개",
    "site2026.about_desc": "국가혁신청(공공기관) 또는 NIA는 국가 혁신 시스템과 스타트업 생태계의 지속적인 발전의 중요성을 인식하고 있습니다. 올해 스타트업 x 이노베이션 태국 엑스포 2026(SITE 2026)은 글로벌 혁신 네트워크를 모으고, 협력을 강화하며, 생태계 강화를 위한 지식 공유를 촉진하기 위해 '글로벌 혁신 영향: 투자의 해'라는 컨셉으로 조직됐다.",
    "site2026.objective_title": "목표",
    "site2026.objective_1": "1. 국내 및 국제적으로 생태계 내 모든 부문(정부, 민간, 학계, 협회) 간 혁신 협력을 강화합니다.",
    "site2026.objective_2": "2. 비즈니스 기회를 창출하고 스타트업과 혁신 기반 기업을 지원합니다.",
    "site2026.objective_3": "3. 경제 확장을 지원하기 위해 동남아시아 및 전 세계에 국제 비즈니스 및 혁신 네트워크를 구축합니다.",
    "site2026.activities_title": "주요 활동",
    "site2026.activity_forum_title": "법정",
    "site2026.activity_forum_desc": "협업, 인공지능, 지속가능성에 중점을 두고 성공적인 혁신 기업의 지식과 비즈니스 관행을 공유하는 세미나입니다.",
    "site2026.activity_exhibition_title": "전시회",
    "site2026.activity_exhibition_desc": "비즈니스 기회 창출, 수익 증대, 투자 촉진을 위한 혁신 기반 기업 및 스타트업을 소개합니다.",
    "site2026.activity_match_title": "비즈니스 매칭",
    "site2026.activity_match_desc": "스타트업 및 혁신 기반 기업과 대기업의 투자 및 사업 확장을 위한 비즈니스 매칭 활동입니다.",
    "site2026.activity_pitch_title": "투구",
    "site2026.activity_pitch_desc": "초기 및 성장 단계의 스타트업과 혁신 기반 기업을 위한 사업 계획 피칭 대회입니다.",
    "site2026.activity_pma_title": "국무총리 표창",
    "site2026.activity_pma_desc": "생태계를 지원하는 잠재력이 높은 스타트업, 기업, 개인을 기리기 위해 국무총리가 주관하는 시상식입니다.",
    "site2026.agenda_title": "이벤트 아젠다",
