    "home.hero_subtitle": "Botnoi Group은 최고의 WebAvatar 에이전트 쇼케이스를 선보입니다. 이 통합 샌드박스에는 자동화된 음성, 양식 작성 및 페이지 라우팅을 위해 구성된 세 가지 지역화된 비즈니스 애플리케이션이 포함되어 있습니다.",
