    "home.tech_desc": "표준 텍스트 기반 봇과 달리 WebAvatar는 DOM을 스캔하고 요소와 직접 상호 작용합니다. 다음 규칙을 준수하여 원활한 탐색과 낮은 토큰 오버헤드를 달성합니다.",
    "home.rule1_title": "이벤트 기반 라우팅",
    "home.rule1_desc": "• 페이지 전환을 위해 취소 가능한 'webavatar-navigate' CustomEvent 전달\n• 단일 페이지 라우팅을 가로채서 React Router를 동적으로 업데이트\n• 전체 페이지 다시 로드를 방지하고 실시간 음성 세션 유지",
    "home.rule2_title": "선언적 포커스 후크",
    "home.rule2_desc": "• 고유한 DOM 요소 ID(예: nav-about, nav-contact)를 사용하여 요소 고정\n• 부드러운 스크롤링 및 초점 링 애니메이션 동적 트리거\n• 시각적 강조 표시를 아바타 음성과 동기화",
    "home.rule3_title": "동적 폼 및 입력 검증",
    "home.rule3_desc": "• 클라이언트 측 양식을 표준 HTML5 입력 유효성 검사에 연결\n• 기본 입력 이벤트를 전달하여 React 구성 요소 상태 업데이트\n• 실시간 반응형 피드백 및 성공 표시기 제공",
