    "contact.faq_heading": "자주 묻는 질문",
    "contact.faq_subheading": "우리 서비스에 대한 빠른 답변을 읽어보세요. WebAvatar는 여기로 스크롤하여 세부정보를 검토할 수 있습니다!",
    "contact.faq_q1": "WebAvatar는 무엇이며 내 사이트에 어떻게 통합됩니까?",
    "contact.faq_a1": "WebAvatar는 경량 JavaScript SDK(맞춤형 스크립트 태그)를 통해 로드되는 시각적 디지털 인간 비서입니다. 표준 브라우저 웹 레이어 내에서 실행되며 페이지를 탐색하고, 지정된 HTML 요소(예: #pricing)로 스크롤하고, 기본 SPA(단일 페이지 앱) 경로를 트리거하고, 합성 음성을 사용하여 방문자를 음성으로 안내할 수 있습니다.",
    "contact.faq_q2": "음성 모델이 연속적인 태국어 음향을 지원합니까?",
    "contact.faq_a2": "예. 당사의 생성 음성 모델은 지역 오디오 아카이브에서 훈련되어 지속적인 태국 방언에 대한 풍부한 음향 매핑을 제공하고 자연스러운 속도, 단어 연결 및 현지 청중에게 적합한 어조 변화를 완벽하게 제공합니다.",
    "contact.faq_q3": "디지털 아바타의 시각적 모양을 사용자 정의할 수 있나요?",
    "contact.faq_a3": "전적으로. Botnoi Group은 맞춤형 3D 모델 리그, 시각적 테마 스킨 및 전문 브랜드 표현을 지원합니다. 회사 마스코트, 공인 또는 가상 브랜드 홍보대사를 직접 모델로 한 아바타를 만들 수 있습니다.",
    "contact.faq_q4": "Botnoi Group의 창립자는 누구입니까?",
    "contact.faq_a4": "Winn 박사는 Botnoi Group의 선구적인 창립자이자 CEO입니다. 그는 방콕 와타나에 있는 본사에서 핵심 AI 연구 부서, 음성 기술 연구소, 디지털 인간 아바타 통합을 조정합니다.",
