    "about.badge": "회사 소개",
    "about.title": "현지화된 AI 솔루션 선도",
    "about.subtitle": "Botnoi Group은 2017년 방콕에서 설립되어 동남아시아 선도 엔터프라이즈 AI 기업 중 하나로 성장했습니다. 우리는 다국어·다문화 시장을 위한 현지화 AI 솔루션을 구축하며, 조직이 현지 언어, 비즈니스 관행, 고객 기대를 이해하는 AI를 도입할 수 있도록 돕습니다.",
    "about.intro_lead": "Botnoi Group은 2017년 방콕에서 설립되어 동남아시아 선도 엔터프라이즈 AI 기업 중 하나로 성장했습니다.",
    "about.intro_sub": "우리는 다국어·다문화 시장을 위한 현지화 AI 솔루션을 구축하며, 조직이 현지 언어, 비즈니스 관행, 고객 기대를 이해하는 AI를 도입할 수 있도록 돕습니다.",
    "about.purpose_title": "우리의 목적",
    "about.vision_title": "우리의 비전",
    "about.vision_desc": "동남아시아 선도 AI 기업이 되어, 현지화된 AI를 통해 모든 조직이 더 스마트하게 일하고, 더 잘 소통하며, 자신 있게 혁신할 수 있도록 지원합니다.",
    "about.mission_title": "우리의 미션",
    "about.mission_desc": "고급 AI를 실용적이고 안전하며 접근 가능하게 만들어 전문 인력 부족 문제를 해결하고, 실제 기업 요구에 맞춘 AI 솔루션으로 비즈니스를 지원합니다.",
    "about.vision_cta": "엔터프라이즈 팀 문의",
    "about.perf_badge": "검증된 성과",
    "about.perf_title": "우리의 성과와 결실",
    "about.perf_desc": "지난 8년간 Botnoi는 AI 생태계를 지속적으로 확장하며 기업, 정부 기관, 수백만 명의 최종 사용자에게 서비스를 제공해 왔습니다. 오늘날 당사의 기술은 동남아시아 전역의 고객 서비스, 음성 AI, 의료, 교육, 금융 및 기업 자동화를 지원하고 있습니다.",
    "about.stat1_num": "100+",
    "about.stat1_title": "엔터프라이즈 프로젝트",
    "about.stat1_desc": "기업 및 공공기관을 위한 AI 솔루션을 성공적으로 구축 및 제공.",
    "about.stat2_num": "10+",
    "about.stat2_title": "AI 제품군",
    "about.stat2_desc": "음성 AI, 챗봇, 번역, 헬스케어 및 자동화를 아우르는 종합 AI 플랫폼.",
    "about.stat3_num": "10M+",
    "about.stat3_title": "활성 사용자",
    "about.stat3_desc": "매월 수백만 명의 사용자가 Botnoi AI 제품을 활발히 이용하고 있습니다.",
    "about.stat4_num": "20M+",
    "about.stat4_title": "파트너 MOU",
    "about.stat4_desc": "대학, 주요 기업 및 정부 기관과의 전략적 협력 관계 체결.",
    "about.journey_badge": "주요 이정표",
    "about.journey_title": "우리의 여정",
    "about.journey_subtitle": "AI 혁신의 10년",
    "about.journey_desc": "2016년 이래 BOTNOI는 수상 경력에 빛나는 챗봇 기술부터 엔터프라이즈 AI 플랫폼, 음성 AI, 글로벌 전략적 파트너십, 차세대 AI 솔루션에 이르기까지 AI 역량을 꾸준히 확장해 왔습니다. 모든 이정표는 기업이 확신을 가지고 AI를 도입하고 실질적인 성과를 거둘 수 있도록 돕겠다는 당사의 약속을 증명합니다.",
    "about.t_2016_title": "LINE Bot Awards 수상",
    "about.t_2016_desc": "• 권위 있는 지역 LINE Bot Awards 수상\n• 현지화 대화형 AI 및 태국어 NLP 아키텍처 개척",
    "about.t_2017_title": "첫 번째 엔터프라이즈 고객",
    "about.t_2017_desc": "• 첫 대형 엔터프라이즈 고객사 시스템 성공적 도입\n• 상용 환경 규모의 지능형 자동 고객 서비스 구축",
    "about.t_2018_title": "챗봇 플랫폼 런칭",
    "about.t_2018_desc": "• 로우코드 Botnoi 챗봇 제작 플랫폼 대외 공개\n• 수천 개의 중소기업 및 개발자 커뮤니티로 확장",
    "about.t_2023_title": "BOTNOI Voice 플랫폼 런칭",
    "about.t_2023_desc": "• 최첨단 BOTNOI Voice TTS 및 음성 복제 플랫폼 런칭\n• 100여 개 이상의 자연스러운 동남아시아 합성 음성 탑재",
    "about.t_2024_title": "AWS 전략적 파트너십",
    "about.t_2024_desc": "• Amazon Web Services (AWS)와 전략적 기업용 AI 파트너십 체결\n• 확장 가능한 생성형 AI 및 클라우드 추론 인프라 대폭 확장",
    "about.t_2025_title": "Voicebot 플랫폼 런칭",
    "about.t_2025_desc": "• 실시간 AI Voicebot 전화 텔레포니 플랫폼 공식 출시\n• 대규모 인바운드 고객 상담 및 아웃바운드 콜 자동화 구현",
    "about.t_2026_title": "100+ 엔터프라이즈 고객 달성",
    "about.t_2026_desc": "• 이정표 달성: 100개 이상의 주요 기업 및 공공기관 고객사 확보\n• 동남아시아 전역에서 월간 활성 상호작용 1,000만 건 이상 기록",
    "about.t_2027_title": "AI 아바타 플랫폼 런칭",
    "about.t_2027_desc": "• 차세대 3D 인터랙티브 WebAvatar 플랫폼 출시\n• 실시간 대화 인텔리전스를 갖춘 자율 웹 내비게이션 에이전트 구현",
    "about.gap_title": "전문 지식의 격차 해소",
    "about.gap_desc": "현대 기업은 숙련된 전문가 부족에 직면해 있으며 고객의 기대치는 지속적으로 높아지고 있습니다. Botnoi AI는 조직이 전문 지식을 확장하고 일관된 서비스를 제공하며 비용을 절감하고 혁신을 가속화할 수 있도록 지원합니다.",
    "about.pillar1_tag": "전문 지식 확장",
    "about.pillar1_title": "전문 지식 확장",
    "about.pillar1_desc": "AI를 통해 도메인 전문성을 체계화하고 복제하여 연중무휴 24시간 활용.",
    "about.pillar2_tag": "24/7 무중단 서비스",
    "about.pillar2_title": "24/7 일관된 서비스",
    "about.pillar2_desc": "언제나 한결같은 품질로 정확하고 신뢰할 수 있는 응답 제공.",
    "about.pillar3_tag": "혁신 가속화",
    "about.pillar3_title": "혁신 가속화",
    "about.pillar3_desc": "반복적인 일상 업무를 자동화하여 전문가가 핵심 전략 업무에 집중할 수 있도록 지원.",
    "about.pillar4_tag": "높은 효율성",
    "about.pillar4_title": "운영 비용 절감",
    "about.pillar4_desc": "AI 기반의 높은 효율성으로 수천 건의 동시 상호작용을 원활하게 처리.",
    "about.products_badge": "엔터프라이즈 솔루션",
    "about.products_title": "우리의 제품",
    "about.products_subtitle": "산업별 맞춤 솔루션",
