    "site2026.title": "Página del evento SITIO 2026",
    "site2026.badge": "Impacto de la innovación global: el año de la inversión",
    "site2026.hero_title": "Startup x Innovación Tailandia Expo 2026",
    "site2026.hero_subtitle": "25 - 27 de junio de 2026 en el Centro Nacional de Convenciones Queen Sirikit (QSNCC)",
    "site2026.about_title": "ACERCA DEL SITIO 2026",
    "site2026.about_desc": "La Agencia Nacional de Innovación (Organización Pública) o NIA reconoce la importancia de desarrollar continuamente el sistema nacional de innovación y el ecosistema de startups. Este año, Startup x Innovation Tailandia Expo 2026 o SITE 2026 se organiza bajo el concepto 'Impacto de la innovación global: el año de la inversión' para reunir redes globales de innovación, elevar la cooperación y promover el intercambio de conocimientos para fortalecer el ecosistema.",
    "site2026.objective_title": "Objetivos",
    "site2026.objective_1": "1. Elevar la cooperación en innovación entre todos los sectores del ecosistema (gubernamental, privado, académico, asociaciones) tanto a nivel local como internacional.",
    "site2026.objective_2": "2. Crear oportunidades de negocio y apoyar a startups y empresas basadas en la innovación.",
    "site2026.objective_3": "3. Establecer redes internacionales de negocios e innovación en el sudeste asiático y a nivel mundial para apoyar la expansión económica.",
    "site2026.activities_title": "PRINCIPALES ACTIVIDADES",
    "site2026.activity_forum_title": "Foro",
    "site2026.activity_forum_desc": "Seminarios para compartir conocimientos y prácticas comerciales de empresas de innovación exitosas, centrándose en la colaboración, la inteligencia artificial y la sostenibilidad.",
    "site2026.activity_exhibition_title": "Exhibición",
    "site2026.activity_exhibition_desc": "Muestra de empresas y startups basadas en la innovación para crear oportunidades de negocio, aumentar los ingresos y estimular la inversión.",
    "site2026.activity_match_title": "Emparejamiento de negocios",
    "site2026.activity_match_desc": "Actividades de vinculación de negocios para generar inversión y expansión comercial para startups y empresas basadas en la innovación con grandes corporaciones.",
    "site2026.activity_pitch_title": "Cabeceo",
    "site2026.activity_pitch_desc": "Concurso de presentación de planes de negocios para nuevas empresas en etapa inicial y de crecimiento y empresas basadas en la innovación.",
    "site2026.activity_pma_title": "Premio del Primer Ministro",
