    "home.tech_title": "Motor WebAvatar",
    "home.tech_subtitle": "Ejecución unificada del agente e interoperabilidad del sitio",
    "home.tech_desc": "A diferencia de los bots estándar basados ​​en texto, WebAvatar escanea el DOM e interactúa directamente con los elementos. Logra una navegación fluida y una baja sobrecarga de tokens al cumplir con las siguientes reglas:",
    "home.rule1_title": "Enrutamiento basado en eventos",
    "home.rule1_desc": "• Envía CustomEvents 'webavatar-navigate' cancelables para transiciones\n• Intercepta el enrutamiento de página única para actualizar React Router\n• Evita recargas completas de páginas y mantiene intacta la sesión de voz",
    "home.rule2_title": "Ganchos de enfoque declarativo",
    "home.rule2_desc": "• Ancla elementos utilizando ID de elemento DOM únicos (p. ej., nav-about, nav-contact)\n• Activa dinámicamente un desplazamiento suave y animaciones focales\n• Sincroniza resaltados visuales con el habla del avatar",
    "home.rule3_title": "Validación dinámica de formularios y entradas",
    "home.rule3_desc": "• Conecta formularios del lado del cliente con validaciones HTML5 estándar\n• Activa eventos de entrada nativos para actualizar estados de React\n• Proporciona comentarios reactivos en tiempo real e indicadores de éxito",
    "home.click_to_call": "Haga clic en el logo para iniciar la llamada",
    "home.tech_cta": "Implemente WebAvatar en su sitio",
