    "about.badge": "Quiénes somos",
    "about.title": "Pioneros en soluciones de IA localizadas",
    "about.subtitle": "Fundado en 2017 en Bangkok, Botnoi Group se ha convertido en una de las principales empresas de IA empresarial del sudeste asiático. Construimos soluciones de IA localizadas diseñadas para mercados multilingües y multiculturales, ayudando a las organizaciones a implementar IA que comprende los idiomas locales, las prácticas comerciales y las expectativas de los clientes.",
    "about.intro_lead": "Fundado en 2017 en Bangkok, Botnoi Group se ha convertido en una de las principales empresas de IA empresarial del sudeste asiático.",
    "about.intro_sub": "Construimos soluciones de IA localizadas diseñadas para mercados multilingües y multiculturales, ayudando a las organizaciones a implementar IA que comprende los idiomas locales, las prácticas comerciales y las expectativas de los clientes.",
    "about.purpose_title": "Nuestro propósito",
    "about.vision_title": "Nuestra Visión",
    "about.vision_desc": "Convertirnos en la empresa de IA líder en el sudeste asiático, brindando IA localizada que permita a cada organización trabajar de manera más inteligente, comunicarse mejor e innovar con confianza.",
    "about.mission_title": "Nuestra Misión",
    "about.mission_desc": "Resolver la escasez de experiencia humana haciendo que la IA avanzada sea práctica, segura y accesible, empoderando a las empresas con soluciones de IA diseñadas para las necesidades reales de las empresas.",
    "about.vision_cta": "Contactar al equipo empresarial",
    "about.perf_badge": "Impacto comprobado",
    "about.perf_title": "Nuestro desempeño y logros",
    "about.perf_desc": "Durante los últimos ocho años, Botnoi ha expandido continuamente su ecosistema de IA, sirviendo a empresas, organizaciones gubernamentales y millones de usuarios finales. Hoy, nuestras tecnologías impulsan el servicio al cliente, la IA de voz, la atención médica, la educación, las finanzas y la automatización empresarial en todo el sudeste asiático.",
    "about.stat1_num": "100+",
    "about.stat1_title": "Proyectos empresariales",
    "about.stat1_desc": "Soluciones de IA entregadas exitosamente para empresas y entidades públicas.",
    "about.stat2_num": "10+",
    "about.stat2_title": "Productos de IA",
    "about.stat2_desc": "Plataformas integrales de IA que abarcan Voz AI, Chatbots, Traducción, Salud y Automatización.",
    "about.stat3_num": "10M+",
    "about.stat3_title": "Usuarios finales",
    "about.stat3_desc": "Millones de usuarios interactúan con los productos de Botnoi AI cada mes.",
    "about.stat4_num": "20M+",
    "about.stat4_title": "MOU con socios",
    "about.stat4_desc": "Colaboraciones estratégicas con universidades, corporaciones y organismos públicos.",
    "about.journey_badge": "Hitos",
    "about.journey_title": "Nuestro recorrido",
    "about.journey_subtitle": "Una década de innovación en IA",
    "about.journey_desc": "Desde 2016, BOTNOI ha expandido continuamente sus capacidades de IA, desde tecnología de chatbot premiada hasta plataformas de IA empresarial, IA de voz, alianzas globales estratégicas y soluciones de IA de próxima generación. Cada hito refleja nuestro compromiso de ayudar a las empresas a adoptar IA con confianza e impacto medible.",
    "about.t_2016_title": "Ganador del LINE Bot Awards",
    "about.t_2016_desc": "• Ganador del prestigioso certamen regional LINE Bot Awards\n• Pionero en IA conversacional localizada y arquitecturas NLP en tailandés",
    "about.t_2017_title": "Primer cliente empresarial",
    "about.t_2017_desc": "• Incorporación exitosa del primer gran cliente empresarial\n• Despliegue de inteligencia de servicio al cliente a escala de producción",
