    "home.badge": "Bac à sable WebAvatar",
    "home.hero_title": "Rencontrez votre\nreprésentant numérique",
    "home.hero_subtitle": "Botnoi Group présente la vitrine ultime pour les agents WebAvatar. Ce bac à sable unifié comprend trois applications métier localisées configurées pour l'automatisation de la parole, du remplissage de formulaires et du routage des pages.",
    "home.btn_explore": "Explorez les cas d'utilisation de démonstration",
    "home.btn_tech": "Comment fonctionne la navigation",
    "home.mockup_title": "Représentant numérique WebAvatar",
    "home.mockup_desc": "Notre avatar visuel lit les structures des pages Web, remplit des entrées complexes, sélectionne les éléments des listes déroulantes et gère la navigation en interne. Essayez de prononcer des commandes telles que « aller à la réservation de vol » ou « montrez-moi l'option de nourriture au curry vert ».",
    "home.btn_request_live": "Demander une démo en direct",
    "home.btn_launch_usecases": "Cas d'utilisation de lancement",
    "home.mockup_avatar_title": "Botnoi - Avatar numérique",
    "home.mockup_awaiting": "EN ATTENTE DE COMMANDE...",
    "home.stats_clients": "Clients actifs",
    "home.stats_voices": "Voix réalistes",
    "home.stats_languages": "Langues prises en charge",
    "home.stats_projects": "Projets de démonstration",
    "home.show_details": "Afficher les détails",
    "home.hide_details": "Masquer les détails",
    "home.select_usecase": "Sélectionnez un cas d'utilisation de démonstration",
    "home.usecase_subtitle": "Choisissez une application métier interactive ci-dessous. Tous les itinéraires sont détectables par le scanner WebAvatar.",
    "home.card_flight_title": "Réservation de vols",
    "home.card_flight_desc": "• Recherche de vols nationaux et configuration des passagers\n• Plan de cabine interactif et génération de carte d'embarquement\n• Simulation complète de réservation de vols",
    "home.card_flight_cta": "Lancer la démo de réservation de vols",
    "home.card_food_title": "Restaurant Botnoi",
    "home.card_food_desc": "• Catalogue de menus thaïlandais et internationaux avec photos\n• Panier interactif et personnalisation du niveau d'épice\n• Envoi de commandes en temps réel et assistant vocal",
    "home.card_food_cta": "Lancer la démo de restaurant",
    "home.card_alldemo_title": "Portail de toutes les démos",
    "home.card_alldemo_desc": "• Centre complet d'applications bac à sable (Vols, IT Store, Restaurant, Hôtel)\n• Portail de présentation des projets web étudiants StartUP (TN01–TN20)\n• Recherche avancée, filtrage par catégorie et exécution de démos",
    "home.card_alldemo_cta": "Lancer le portail de toutes les démos",
    "home.card_itstore_title": "Boutique IT E-commerce",
    "home.card_itstore_desc": "• Vitrine d'électronique grand public et filtres par catégorie\n• Gestion du panier et paiement de la commande\n• Facturation instantanée et reçus numériques",
    "home.card_itstore_cta": "Lancer la démo de l'IT Store",
    "home.card_hotel_title": "Hôtel Botnoi",
    "home.card_hotel_desc": "• Catalogue de chambres en temps réel et recherche de disponibilité\n• Sélection interactive des dates et calcul automatique du tarif\n• Confirmation de réservation et affichage des certificats",
    "home.card_hotel_cta": "Lancer la Démo Hôtel",
    "home.card_contact_title": "Formulaire de demande de vente B2B",
    "home.card_contact_desc": "• Formulaire de capture de leads de qualité avec validation des données\n• Sélection dynamique des demandes et accordéons FAQ interactifs\n• Registre des demandes de contact pour les administrateurs",
    "home.card_contact_cta": "Lancer la démo d'enquête B2B",
    "marquee.botnoi_air": "Botnoi Air",
    "marquee.botnoi_restaurant": "Restaurant Botnoi",
    "marquee.webavatar": "WebAvatar",
    "marquee.flight_booking": "Réservation de vols",
    "marquee.food_ordering": "Commande de repas",
    "marquee.voice_ai": "IA Vocale",
    "home.tech_title": "Moteur WebAvatar",
    "home.tech_subtitle": "Exécution unifiée des agents et interopérabilité des sites",
    "home.tech_desc": "Contrairement aux robots textuels standard, WebAvatar analyse le DOM et interagit directement avec les éléments. Il permet une navigation fluide et une faible surcharge de jetons en adhérant aux règles suivantes :",
    "home.rule1_title": "Routage piloté par les événements",
    "home.rule1_desc": "• Envoie des CustomEvents « webavatar-navigate » annulables pour les transitions\n• Intercepte le routage sur une seule page pour mettre à jour React Router\n• Empêche les rechargements complets et préserve la session vocale",
    "home.rule2_title": "Crochets de focus déclaratifs",
    "home.rule2_desc": "• Ancre les éléments à l'aide d'identifiants d'élément DOM uniques (ex. nav-about, nav-contact)\n• Déclenche dynamiquement un défilement fluide et des animations focales\n• Synchronise les surbrillances visuelles avec la parole de l'avatar",
    "home.rule3_title": "Validation dynamique des formulaires et entrées",
    "home.rule3_desc": "• Connecte les formulaires côté client aux validations HTML5 standard\n• Déclenche des événements d'entrée natifs pour mettre à jour les états React\n• Fournit des retours réactifs en temps réel et des indicateurs de réussite",
    "home.click_to_call": "Cliquez sur le logo pour démarrer l'appel",
    "home.tech_cta": "Déployez WebAvatar sur votre site",
    "home.features_heading": "Caractéristiques et contraintes du moteur",
    "home.feat1": "Prend en charge l'analyse continue des scripts thaïlandais",
    "home.feat2": "Projection de coordonnées de fenêtre dynamique",
    "home.feat3": "Transitions du modèle de parole bilingue",
    "home.feat4": "Zéro suivi de cookies ou de scripts tiers",
    "itstore.title": "Botnoi Tech Hub · Boutique Phare",
