    "contact.form_submit": "Soumettre une demande Sandbox",
    "contact.form_filling": "Soumission...",
    "contact.faq_heading": "Foire aux questions",
    "contact.faq_subheading": "Lisez des réponses rapides sur nos services. Votre WebAvatar peut faire défiler ici pour consulter les détails !",
    "contact.faq_q1": "Qu'est-ce que WebAvatar et comment s'intègre-t-il dans mon site ?",
    "contact.faq_a1": "WebAvatar est un assistant humain numérique visuel chargé via un SDK JavaScript léger (notre balise de script personnalisée). Il s'exécute dans les couches Web standard du navigateur et peut parcourir les pages, faire défiler jusqu'aux éléments HTML désignés (comme #pricing), déclencher des itinéraires natifs d'application monopage (SPA) et guider verbalement vos visiteurs à l'aide d'un discours synthétique.",
    "contact.faq_q2": "Le modèle vocal prend-il en charge l’acoustique thaïlandaise continue ?",
    "contact.faq_a2": "Oui. Nos modèles vocaux génératifs sont formés sur des archives audio régionales, offrant une cartographie acoustique riche pour les dialectes thaïlandais continus, complétée par un rythme naturel, un pontage de mots et une inflexion de ton adaptée au public local.",
    "contact.faq_q3": "Puis-je personnaliser l’apparence visuelle de l’avatar numérique ?",
    "contact.faq_a3": "Absolument. Botnoi Group prend en charge les modèles 3D personnalisés, les skins de thèmes visuels et les représentations de marques spécialisées. Nous pouvons créer un avatar directement inspiré de la mascotte de votre entreprise, d’une personnalité publique ou d’un ambassadeur virtuel de votre marque.",
    "contact.faq_q4": "Qui est le fondateur exécutif du groupe Botnoi ?",
    "contact.faq_a4": "Le Dr Winn est le fondateur visionnaire et président-directeur général du groupe Botnoi. Il coordonne notre division principale de recherche sur l'IA, les laboratoires de technologie vocale et les intégrations d'avatars humains numériques depuis notre siège social de Watthana, Bangkok.",
