    "showcase.no_projects_desc": "Essayez d'ajuster vos filtres de recherche ou vos requêtes.",
    "showcase.desc_accommodation": "• Catalogue de chambres en temps réel et recherche de disponibilité\n• Sélection interactive des dates et calcul automatique du tarif\n• Confirmation de réservation et affichage des certificats",
    "showcase.desc_flight": "• Recherche de vols nationaux et configuration des passagers\n• Plan de cabine interactif et génération de carte d'embarquement\n• Simulation complète de réservation de vols",
    "showcase.desc_restaurant": "• Menu numérique catégorisé pour les commandes\n• Gestion du panier d'achat et résumé de la commande\n• Calcul instantané de l'addition et reçus en direct",
    "showcase.desc_ecommerce": "• Vitrine d'électronique grand public et filtres par catégorie\n• Gestion du panier et paiement de la commande\n• Facturation instantanée et reçus numériques",
    "showcase.desc_tn01": "• Catalogue complet de cours en ligne et leçons\n• Suivi de progression et quiz interactifs\n• Certification automatique de fin de formation",
    "showcase.desc_tn03": "• Analyse dermatologique de la peau et conseils routine\n• Filtrage des ingrédients selon le type de peau\n• Panier en ligne et confirmation de commande",
    "showcase.desc_tn04": "• Cartographie d'itinéraires et recherche de lieux\n• Planification de trajets et estimation du temps\n• Recommandations de lieux incontournables",
    "showcase.desc_tn05": "• Rendez-vous médicaux en ligne et annuaire des services\n• Bilans de santé et packages de centres médicaux\n• Dossiers médicaux personnels et comptes rendus",
    "showcase.desc_tn06": "• Services vocaux thaïlandais (STT, TTS, Clonage Vocale)\n• Chatbot IA conversationnel et API de modèles linguistiques\n• Documentation SDK développeur et formules d'abonnement",
    "showcase.desc_tn07": "• Menu numérique et réservation de table en ligne\n• Personnalisation des plats et ingrédients sur mesure\n• Résumé de commande en temps réel et facturation",
    "showcase.desc_tn08": "• Showrooms virtuels et catalogue de meubles\n• Inspirations d'aménagement intérieur pour espaces de vie\n• Commande et paiement en ligne fluides",
    "showcase.desc_tn09": "• Traduction vocale voix-à-voix en temps réel\n• Synthèse vocale naturelle (TTS) et conversion de voix\n• Lecture audio et traduction multilingue",
    "showcase.desc_tn10": "• Prise de rendez-vous technicien climatisation et entretien\n• Tarifs transparents et forfaits de nettoyage\n• Suivi du statut d'intervention du technicien en direct",
    "showcase.desc_tn11": "• Consultation en ligne avec pharmacien(ne)s diplômé(e)s\n• Évaluation initiale des symptômes et conseils sur les médicaments\n• Service de livraison de médicaments à domicile en toute sécurité",
    "showcase.desc_tn12": "• Plateforme de recherche immobilière et logements\n• Visites virtuelles et catalogue de projets\n• Consultations d'agents en ligne et rendez-vous",
    "showcase.desc_tn14": "• Commande de grains de café spécialisés et carte du café\n• Sélection de torréfaction, taux de sucre et adjonctions\n• Click & collect et programme de fidélité",
    "showcase.desc_tn15": "• Assistant de réservation spa médical et bien-être\n• Forfaits de soins et consultations de spécialistes\n• Prise de rendez-vous en ligne avec confirmation immédiate",
    "showcase.desc_tn16": "• Plateforme intégrée de fitness et d'entraînement\n• Planning d'exercices, réservation de coachs et suivi\n• Conseils de nutrition personnalisés et plans de repas",
    "showcase.desc_tn17": "• Plateforme d'IA pour boutiques de commerce électronique\n• Réponses chatbot, closing de vente et recommandations produits\n• Vérification des stocks 24/7 et service client automatisé",
    "showcase.desc_tn19": "• Showrooms virtuels et catalogue de meubles\n• Inspirations d'aménagement intérieur pour espaces de vie\n• Commande et paiement en ligne fluides",
