    "about.badge": "Qui sommes-nous",
    "about.title": "Pionniers des solutions d'IA localisées",
    "about.subtitle": "Fondé en 2017 à Bangkok, Botnoi Group est devenu l'une des entreprises leaders en IA d'entreprise en Asie du Sud-Est. Nous concevons des solutions d'IA localisées adaptées aux marchés multilingues et multiculturels, permettant aux organisations de déployer une IA qui comprend les langues locales, les pratiques commerciales et les attentes des clients.",
    "about.intro_lead": "Fondé en 2017 à Bangkok, Botnoi Group est devenu l'une des entreprises leaders en IA d'entreprise en Asie du Sud-Est.",
    "about.intro_sub": "Nous concevons des solutions d'IA localisées adaptées aux marchés multilingues et multiculturels, permettant aux organisations de déployer une IA qui comprend les langues locales, les pratiques commerciales et les attentes des clients.",
    "about.purpose_title": "Notre mission et raison d'être",
    "about.vision_title": "Notre Vision",
    "about.vision_desc": "Devenir l'entreprise d'IA leader en Asie du Sud-Est en fournissant une IA localisée qui permet à chaque organisation de travailler plus intelligemment, de mieux communiquer et d'innover en toute confiance.",
    "about.mission_title": "Notre Mission",
    "about.mission_desc": "Résoudre la pénurie d'expertise humaine en rendant l'IA avancée pratique, sécurisée et accessible, en offrant aux entreprises des solutions d'IA conçues pour les exigences concrètes du monde professionnel.",
    "about.vision_cta": "Contacter l'équipe entreprise",
    "about.perf_badge": "Impact prouvé",
    "about.perf_title": "Nos performances et réussites",
    "about.perf_desc": "Au cours des huit dernières années, Botnoi a continuellement étendu son écosystème d'IA, au service d'entreprises, d'organismes gouvernementaux et de millions d'utilisateurs finaux. Aujourd'hui, nos technologies propulsent le service client, l'IA vocale, la santé, l'éducation, la finance et l'automatisation d'entreprise à travers toute l'Asie du Sud-Est.",
    "about.stat1_num": "100+",
    "about.stat1_title": "Projets d'entreprise",
    "about.stat1_desc": "Solutions d'IA déployées avec succès pour les entreprises et les organismes publics.",
    "about.stat2_num": "10+",
    "about.stat2_title": "Produits d'IA",
    "about.stat2_desc": "Plateformes d'IA complètes couvrant la voix IA, les chatbots, la traduction, la santé et l'automatisation.",
    "about.stat3_num": "10M+",
    "about.stat3_title": "Utilisateurs finaux",
    "about.stat3_desc": "Des millions d'utilisateurs interagissent chaque mois avec les produits Botnoi AI.",
    "about.stat4_num": "20M+",
    "about.stat4_title": "Accords de partenariat (MOU)",
    "about.stat4_desc": "Collaborations stratégiques avec des universités, des entreprises et des institutions publiques.",
    "about.journey_badge": "Jalons historiques",
    "about.journey_title": "Notre parcours",
    "about.journey_subtitle": "Une décennie d'innovation en IA",
    "about.journey_desc": "Depuis 2016, BOTNOI n'a cessé d'élargir ses capacités en IA — des chatbots primés aux plateformes d'IA d'entreprise, à l'IA vocale, aux partenariats stratégiques mondiaux et aux solutions d'IA de nouvelle génération. Chaque étape reflète notre engagement à aider les entreprises à adopter l'IA avec confiance et un impact mesurable.",
    "about.t_2016_title": "Lauréat des LINE Bot Awards",
    "about.t_2016_desc": "• Vainqueur du prestigieux concours régional LINE Bot Awards\n• Pionnier de l'IA conversationnelle localisée et du NLP thaïlandais",
    "about.t_2017_title": "Premier client grand compte",
    "about.t_2017_desc": "• Intégration réussie du premier grand compte entreprise\n• Déploiement d'une intelligence de service client automatisée à l'échelle de production",
    "about.t_2018_title": "Lancement de la plateforme Chatbot",
    "about.t_2018_desc": "• Lancement public de la plateforme de création de chatbots low-code Botnoi\n• Adoption par des milliers de PME et de développeurs",
    "about.t_2023_title": "Lancement de la plateforme BOTNOI Voice",
    "about.t_2023_desc": "• Lancement de la plateforme de synthèse vocale et de clonage BOTNOI Voice TTS\n• Intégration de plus de 100 voix synthétiques naturelles d'Asie du Sud-Est",
    "about.t_2024_title": "Partenaire stratégique AWS",
    "about.t_2024_desc": "• Conclusion d'un partenariat stratégique IA d'entreprise avec Amazon Web Services (AWS)\n• Déploiement d'une infrastructure cloud évolutive pour l'IA générative",
    "about.t_2025_title": "Lancement de la plateforme Voicebot",
    "about.t_2025_desc": "• Lancement officiel de la plateforme de téléphonie Voicebot IA en temps réel\n• Automatisation à haut volume des appels entrants et sortants pour le support client",
    "about.t_2026_title": "Plus de 100 clients grands comptes",
    "about.t_2026_desc": "• Jalon franchi : plus de 100 clients entreprises et organismes publics\n• Plus de 10 millions d'interactions d'utilisateurs actifs par mois en Asie du Sud-Est",
    "about.t_2027_title": "Lancement de la plateforme Avatar IA",
    "about.t_2027_desc": "• Lancement de la plateforme d'avatars Web 3D interactifs de nouvelle génération\n• Agents de navigation web autonomes dotés d'une intelligence conversationnelle en temps réel",
    "about.gap_title": "Combler le déficit d'expertise",
    "about.gap_desc": "Les entreprises sont confrontées à une pénurie croissante de spécialistes alors que les attentes des clients ne cessent de s'élever. Botnoi AI aide les organisations à démultiplier l'expertise, à offrir un service constant, à réduire les coûts et à accélérer l'innovation.",
    "about.pillar1_tag": "DÉMULTIPLIER L'EXPERTISE",
    "about.pillar1_title": "Déployer le savoir expert",
    "about.pillar1_desc": "Capturer et répliquer l'expertise métier grâce à l'IA, disponible 24h/24 et 7j/7.",
    "about.pillar2_tag": "SERVICE 24/7",
    "about.pillar2_title": "Service continu 24h/24 et 7j/7",
    "about.pillar2_desc": "Fournir des réponses précises et fiables à tout moment avec une qualité constante.",
    "about.pillar3_tag": "INNOVATION",
    "about.pillar3_title": "Accélérer l'innovation",
    "about.pillar3_desc": "Automatiser les tâches récurrentes pour permettre aux experts de se consacrer aux missions stratégiques.",
    "about.pillar4_tag": "HAUTE EFFICACITÉ",
    "about.pillar4_title": "Réduire les coûts d'exploitation",
    "about.pillar4_desc": "Traiter simultanément des milliers d'interactions avec l'efficacité et la rapidité de l'IA.",
